import {graphql} from 'react-relay'

export const query = graphql`
  query BuildPageQuery($buildLocator: String!) {
    build(buildLocator: $buildLocator) {
      pipelineRun {
        pipeline {
          id
        }
      }
      pipelineRunJob {
        pipelineRun {
          build {
            id
          }
          pipeline {
            id
          }
        }
      }
    }
  }
`
