export type StatusRequest = ProjectStatusRequest | BuildTypeStatusRequest | PipelineStatusRequest
export const getProjectStatusRequest: (
  projectId?: ProjectId,
  branch?: Branch | null,
) => StatusRequest = (id, branch) => ({
  type: 'project',
  id,
  branch,
})
export const getBuildTypeStatusRequest: (
  buildTypeId?: BuildTypeId,
  branch?: Branch | null,
) => StatusRequest = (id, branch) => ({
  type: 'bt',
  id,
  branch,
})
export const getPipelineStatusRequest: (
  pipelineId?: PipelineId,
  branch?: Branch | null,
) => StatusRequest = (id, branch) => ({
  type: 'pipeline',
  id,
  branch,
})

type StatusRequestArgs =
  | {
      type: 'project'
      id: ProjectId
      branch?: Branch | null
    }
  | {
      type: 'bt'
      id?: BuildTypeId
      branch?: Branch | null
    }
  | {
      type: 'pipeline'
      id?: PipelineId
      branch?: Branch | null
    }
export function getStatusRequest({type, id, branch}: StatusRequestArgs): StatusRequest {
  switch (type) {
    case 'project':
      return getProjectStatusRequest(id, branch)
    case 'pipeline':
      return getPipelineStatusRequest(id, branch)
    default:
      return getBuildTypeStatusRequest(id, branch)
  }
}

