export const getBuildTypeFilter: (arg0: BuildTypeId) => ProjectOrBuildTypeNode = memoize(
  (id: BuildTypeId): ProjectOrBuildTypeNode => ({
    nodeType: 'bt',
    id,
  }),
)
export const getPipelineFilter: (pipelineId: PipelineId) => ProjectOrBuildTypeNode = memoize(
  (id: PipelineId): ProjectOrBuildTypeNode => ({
    nodeType: 'pipeline',
    id,
  }),
)
export const getJobFilter: (jobId: string) => ProjectOrBuildTypeNode = memoize(
  (id: string): ProjectOrBuildTypeNode => ({
    nodeType: 'job',
    id,
  }),
)
export const getBatchFilter: ({
  id,
  jobId,
  batchId,
}: {
  id: BuildTypeId
  jobId: string
  batchId?: string
}) => ProjectOrBuildTypeNode = memoize(
  ({id, jobId, batchId}): ProjectOrBuildTypeNode => ({
    nodeType: 'jobBatch',
    jobId,
    id,
    batchId,
  }),
)
export const getProjectFilter: (projectId: ProjectId) => ProjectOrBuildTypeNode = memoize(
  (id: ProjectId): ProjectOrBuildTypeNode => ({
    nodeType: 'project',
    id,
  }),
)
export const getProjectBuildTypeFilter: (
  props: ActiveEntityProps,
) => ProjectOrBuildTypeNode | null = ({projectId, pipelineId, jobId, batchId, buildTypeId}) => {
  if (buildTypeId != null && jobId != null && batchId != null) {
    return getBatchFilter({id: buildTypeId, jobId, batchId})
  }

  if (jobId != null) {
    return getJobFilter(jobId)
  }

  if (pipelineId != null) {
    return getPipelineFilter(pipelineId)
  }

  if (buildTypeId != null) {
    return getBuildTypeFilter(buildTypeId)
  }

  if (projectId != null) {
    return getProjectFilter(projectId)
  }

  return null
}
