import Theme from '@jetbrains/ring-ui-built/components/global/theme'

import store from '../../../store'

export const getCurrentTheme = (): Theme => {
  const stateTheme = store.getState().initialTheme
  const darkMatcher = window.matchMedia('(prefers-color-scheme: dark)')
  const prefersColorScheme = darkMatcher.matches ? Theme.DARK : Theme.LIGHT

  return stateTheme ?? prefersColorScheme
}
