//   href: ?string,
//   params: ?QueryParams | (QueryParams => QueryParams),
//   hash: ?string,
// ) => useLocationSelector(location => getHrefWithQueryParams(location, href, params, hash))
export const isQueueScreen = (pathname: string): boolean =>
  matchRoute(Routes.QUEUE, pathname) != null

// It's not possible to solve this issue with the `react-router`
export function isAgentsScreen(pathname: string) {
  return Boolean(AGENTS_SCREEN_ROUTES.find(route => matchRoute(route, pathname)))
}

export const isPipelinesScreen = (pathname: string): boolean =>
  matchRoute(Routes.PIPELINES, pathname) != null ||
  matchRoute(Routes.PIPELINE_PAGES, pathname) != null

export const isPipelinesEditScreen = (queryParams: QueryParams): boolean =>
  queryParams.edit === 'true'

export const isPipelinesRunScreen = (pathname: string, params: Readonly<Params>): boolean =>
  matchRoute(Routes.PIPELINE_RUN, pathname) != null && !!params.pipelineRunId

const matchAny = (routes: string[], pathname: string) =>
  routes.some(route => matchRoute(route, pathname) != null)

const PROJECT_DOMAIN_BREADCRUMBS_ROUTES = [
  Routes.PROJECT,
  Routes.BUILD_TYPE,
  Routes.BUILD,
  Routes.BUILD_UNKNOWN_BUILDTYPE,
]

export const isProjectDomainBreadcrumbsScreen = (pathname: string) =>
  matchAny(PROJECT_DOMAIN_BREADCRUMBS_ROUTES, pathname)

const AGENT_DOMAIN_BREADCRUMBS_ROUTES = [Routes.AGENT, Routes.AGENT_POOL, Routes.CLOUD_IMAGE]
export const isAgentDomainBreadcrumbsScreen = (pathname: string) =>
  matchAny(AGENT_DOMAIN_BREADCRUMBS_ROUTES, pathname)

const PIPELINE_DOMAIN_NO_BREADCRUMBS_ROUTES = [
  Routes.ALL_PIPELINES,
  Routes.ADD_REPOSITORY,
  Routes.CREATE_PIPELINE,
  Routes.WELCOME_PIPELINES,
]
export const isPipelineDomainBreadcrumbsScreen = (pathname: string) =>
  isPipelinesScreen(pathname) && !matchAny(PIPELINE_DOMAIN_NO_BREADCRUMBS_ROUTES, pathname)

const NO_SIDEBAR_ROUTES = [
  Routes.CHANGES,
  Routes.CHANGE,
  Routes.GUIDES,
  Routes.CREATE_PIPELINE,
  Routes.CREATE_PROJECT,
  Routes.NOTIFICATIONS,
  Routes.WELCOME_PIPELINES,
  Routes.ADD_REPOSITORY,
]
export const isScreenWithSidebar = (pathname: string) => !matchAny(NO_SIDEBAR_ROUTES, pathname)

const SAKURA_UI_ONLY_ROUTES = [
  Routes.COMPARE_BUILDS,
  Routes.GUIDES,
  Routes.PIPELINES,
  Routes.PIPELINE_PAGES,
  Routes.NOTIFICATIONS,
  Routes.CREATE_PROJECT,
]
export const isSakuraUIOnlyScreen = (pathname: string): boolean =>
  matchAny(SAKURA_UI_ONLY_ROUTES, pathname)

const CENTERED_CONTENT_ROUTES = [Routes.NOTIFICATIONS]
export const isCenteredContentScreen = (pathname: string): boolean =>
  matchAny(CENTERED_CONTENT_ROUTES, pathname)

enum CreateType {
  PROJECT = 'createProjectMenu',
  BUILD_TYPE = 'createBuildTypeMenu',
}

function generateCreateEntityHref({projectId, type}: {projectId: ProjectId; type: CreateType}) {
  return resolveRelative('/admin/createObjectMenu.html', {
    projectId: stringifyId(projectId),
    showMode: type,
    cameFromUrl: location.href,
  })
}

export function getCreateBuildTypeHref(projectId: ProjectId) {
  return generateCreateEntityHref({projectId, type: CreateType.BUILD_TYPE})
}

export function getCreatePipelineHref(projectId: ProjectId) {
  return `${getHref(Routes.CREATE_PIPELINE)}?projectId=${projectId}`
}

export function getCreateProjectHref(projectId: ProjectId) {
  if (isCreateProjectNewUiEnabled) {
    return `${getHref(Routes.CREATE_PROJECT)}?projectId=${projectId}`
  } else {
    return generateCreateEntityHref({projectId, type: CreateType.PROJECT})
  }
}

export function getEditUrlFormats() {
  return {
    buildTypeUrlFormat: resolveRelative('/admin/editBuild.html?id=buildType:{id}'),
    projectUrlFormat: resolveRelative('/admin/editProject.html?projectId={id}'),
  }
}
