import * as React from 'react'

import AppRoutes from '../../../routes'

import {AddRepositoryPageEntryPoint} from './AddRepositoryPage/AddRepositoryPage.entryPoint'
import {CreatePipelinePageEntryPoint} from './CreatePipelinePage/CreatePipelinePage.entryPoint'
import {IndexPageEntryPoint} from './IndexPage/IndexPage.entryPoint'
import {PipelinePageEntryPoint} from './PipelinePage/PipelinePage.entryPoint'
import {PipelineRunPageEntryPoint} from './PipelineRunPage/PipelineRunPage.entryPoint'
import PipelinesPagesErrorBoundary from './PipelinesPages.errorBoundary'
import {isWithoutVcsFeatureEnabled} from './utils/featureToggles'
import {WelcomePageEntryPoint} from './WelcomePage/WelcomePage.entryPoint'

const PipelinesPages = React.lazy(
  () =>
    import(
      /* webpackChunkName: "PipelinesPages" */
      './PipelinesPages'
    ),
)

const pipelinesPrefixLength = AppRoutes.PIPELINES.length - 1
const pipelinePrefixLength = AppRoutes.PIPELINE_PAGES.length - 1

export const pipelinesPagesRoutes = [
  {
    path: AppRoutes.PIPELINES,
    Component: PipelinesPages,
    ErrorBoundary: PipelinesPagesErrorBoundary,
    children: [
      {index: true, entryPoint: IndexPageEntryPoint},
      {
        path: AppRoutes.WELCOME_PIPELINES.slice(pipelinesPrefixLength),
        entryPoint: WelcomePageEntryPoint,
      },
      {
        path: AppRoutes.CREATE_PIPELINE.slice(pipelinesPrefixLength),
        entryPoint: CreatePipelinePageEntryPoint,
      },
    ],
  },
  {
    path: AppRoutes.PIPELINE_PAGES,
    Component: PipelinesPages,
    ErrorBoundary: PipelinesPagesErrorBoundary,
    children: [
      ...(isWithoutVcsFeatureEnabled
        ? [
            {
              path: AppRoutes.ADD_REPOSITORY.slice(pipelinePrefixLength),
              entryPoint: AddRepositoryPageEntryPoint,
            },
          ]
        : []),
      {
        path: AppRoutes.PIPELINE_RUN.slice(pipelinePrefixLength),
        entryPoint: PipelineRunPageEntryPoint,
      },
      {
        path: AppRoutes.PIPELINE.slice(pipelinePrefixLength),
        entryPoint: PipelinePageEntryPoint,
      },
    ],
  },
]
