import Dialog from '@jetbrains/ring-ui-built/components/dialog/dialog'
import {Content, Header} from '@jetbrains/ring-ui-built/components/island/island'
import Panel from '@jetbrains/ring-ui-built/components/panel/panel'
import {Button, IconButton} from '@jetbrains/teamcity-ui/components'
import {useEffect, useState} from 'react'
import {graphql, useLazyLoadQuery} from 'react-relay'

import {openWhatsNew} from '../../../actions'
import {useAppDispatch, useAppSelector} from '../../../hooks/react-redux'
import {useSetUserProperty} from '../../../hooks/useSetUserProperty'
import {getServerInfo} from '../../../selectors'
import {trackEvent} from '../../../statistics/statistics.lazy'
import {Permission} from '../../../types'
import {UserProperties} from '../../../utils/userProperties'

import type {WelcomePopupQuery} from './__generated__/WelcomePopupQuery.graphql'
import {
  DEFAULT_PAGE,
  PAGE_CONTENT,
  PAGE_COUNT,
  TITLE,
  TRY_PIPELINES_LINK,
} from './WelcomePopup.consts'

import styles from './WelcomePopup.module.css'

import {isWelcomePopupEnabled} from 'src/components/pages/PipelinesPages/utils/featureToggles'
import {useBooleanUserProperty, useUserProperty} from 'src/hooks/useUserProperty'

const query = graphql`
  query WelcomePopupQuery($locator: String!) {
    userPermissions(userLocator: "current", locator: $locator) {
      count
    }
  }
`

function WelcomePopup() {
  const showPopup = useBooleanUserProperty(UserProperties.SHOW_WELCOME_TO_PIPELINES_POPUP, true)

  const userServerBuildNumber = useUserProperty(UserProperties.SERVER_BUILD_NUMBER)
  const setUserProperty = useSetUserProperty()

  const licenseIsCloud = useAppSelector(state => getServerInfo(state)?.licenseIsCloud)
  const buildNumber = useAppSelector(state => getServerInfo(state)?.buildNumber)
  const isOldUser =
    userServerBuildNumber && buildNumber && Number(userServerBuildNumber) < Number(buildNumber)

  const {userPermissions} = useLazyLoadQuery<WelcomePopupQuery>(query, {
    locator: `permission:${Permission.EDIT_PROJECT},count:1`,
  })

  const [page, setPage] = useState(DEFAULT_PAGE)

  const isLastPage = page === PAGE_COUNT
  const isFirstPage = page === DEFAULT_PAGE
  const currentPageContent = PAGE_CONTENT[page - 1]

  const dispatch = useAppDispatch()

  const onClose = () => {
    setUserProperty(UserProperties.SHOW_WELCOME_TO_PIPELINES_POPUP, 'false')
    trackEvent({name: 'close.click', groupId: 'welcomepopup.events.group'})
    dispatch(openWhatsNew())
  }

  const onPrimaryClick = () => {
    if (isLastPage) {
      onClose()
    } else {
      setPage(prevState => prevState + 1)
      trackEvent({name: 'next.click', groupId: 'welcomepopup.events.group'})
    }
  }

  const onSecondaryClick = () => {
    if (isFirstPage) {
      onClose()
    } else {
      setPage(prevState => prevState - 1)
    }
  }

  const onJoinEapClick = () => {
    trackEvent({name: 'join.eap.click', groupId: 'welcomepopup.events.group'})
    onClose()
  }

  const canBeShown = isWelcomePopupEnabled() && isOldUser && !!userPermissions?.count

  useEffect(() => {
    if (showPopup && canBeShown) {
      trackEvent({name: 'welcome.popup.open', groupId: 'welcomepopup.events.group'})
    }
  }, [canBeShown, showPopup])

  if (!canBeShown) {
    return null
  }

  return (
    <Dialog
      closeButtonInside
      showCloseButton
      show={showPopup}
      label={TITLE}
      contentClassName={styles.dialog}
      onCloseAttempt={onClose}
    >
      <Header>{TITLE}</Header>
      <Content className={styles.content}>
        <div className={styles.subtitle}>{currentPageContent.title}</div>
        <div className={styles.text}>{currentPageContent.text}</div>
        <div className={styles.imageContainer}>
          <img
            src={currentPageContent.image}
            alt={currentPageContent.alt}
            className={styles.image}
          />
        </div>
      </Content>
      <Panel className={styles.pager}>
        {licenseIsCloud ? (
          <Button primary onClick={onPrimaryClick}>
            {isLastPage ? 'Close' : 'Next'}
          </Button>
        ) : (
          <IconButton
            primary
            withBorder
            className={styles.link}
            icon={'new-window'}
            href={TRY_PIPELINES_LINK}
            target="_blank"
            rel="noreferrer"
            title="Open in a new tab"
            onClick={onJoinEapClick}
          >
            {'Join Early Access program'}
          </IconButton>
        )}
        <Button onClick={onSecondaryClick}>{isFirstPage ? 'Dismiss' : 'Back'}</Button>
        {licenseIsCloud ? <div className={styles.number}>{`${page} of ${PAGE_COUNT}`}</div> : null}
      </Panel>
    </Dialog>
  )
}
export default WelcomePopup
