import {graphql} from 'react-relay'

export const pipelineQuery = graphql`
  query PipelinesPagesQuery($locator: String!) {
    pipeline(pipelineLocator: $locator) {
      internalId
      ...SettingsSidebarContentFragment
      ...EditPipelineConfigurationDialogFragment
      headBuildType {
        ...pipelineHeadBuildTypeFragment
      }
      parentProject {
        id
      }
    }
  }
`
