import type {PayloadAction} from '@reduxjs/toolkit'
import {createSlice} from '@reduxjs/toolkit'

export const sidebarSettings = createSlice({
  name: 'sidebarSettings',
  initialState: {
    resizeDelta: 0,
    collapsed: false,
    pinned: true,
    pinDisabled: false,
    autoCollapseDisabled: false,
  },
  reducers: {
    setSidebarCollapsed: (state, action: PayloadAction<boolean>) => {
      state.collapsed = action.payload
    },
    setResizeDelta: (state, action: PayloadAction<number>) => {
      state.resizeDelta = action.payload
    },
    setAutoCollapseDisabled: (state, action: PayloadAction<boolean>) => {
      state.autoCollapseDisabled = action.payload
    },
    togglePinSidebar: state => {
      state.pinned = !state.pinned
      state.collapsed = !state.pinned
    },
    toggleCollapseSidebar: state => {
      state.collapsed = !state.collapsed
    },
    disableSidebarPin: state => {
      state.pinDisabled = true
      if (state.pinned) {
        state.collapsed = true
      }
    },
    enableSidebarPin: state => {
      state.pinDisabled = false
      if (state.pinned) {
        state.collapsed = false
      }
    },
  },
})
