import Button from '@jetbrains/ring-ui-built/components/button/button'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import {useCallback} from 'react'

import {useSetUserProperty} from '../../../../../hooks/useSetUserProperty'
import {useBooleanUserProperty} from '../../../../../hooks/useUserProperty'
import {UserProperties} from '../../../../../utils/userProperties'
import {isPipelinesInterviewRecruitmentBannerEnabled} from '../../utils/featureToggles'

import styles from './PipelinesInterviewRecruitmentBanner.module.css'

const LINK = window.internalProps['teamcity.pipelines.interviewRecruitmentBanner.link']
const BUTTON_NAME = window.internalProps['teamcity.pipelines.interviewRecruitmentBanner.buttonName']
const MAIN_MESSAGE =
  window.internalProps['teamcity.pipelines.interviewRecruitmentBanner.mainMessage']
const ADDITIONAL_MESSAGE =
  window.internalProps['teamcity.pipelines.interviewRecruitmentBanner.additionalMessage']

function PipelinesInterviewRecruitmentBanner() {
  const setUserProperty = useSetUserProperty()

  const isShowInterviewRecruitmentBanner = useBooleanUserProperty(
    UserProperties.SHOW_PIPELINES_INTERVIEW_RECRUITMENT_BANNER,
    true,
  )

  const dismiss = useCallback(
    () => setUserProperty(UserProperties.SHOW_PIPELINES_INTERVIEW_RECRUITMENT_BANNER, 'false'),
    [setUserProperty],
  )

  if (
    !isPipelinesInterviewRecruitmentBannerEnabled ||
    !isShowInterviewRecruitmentBanner ||
    !LINK ||
    !BUTTON_NAME ||
    !MAIN_MESSAGE ||
    !ADDITIONAL_MESSAGE
  ) {
    return null
  }

  return (
    <>
      <div className={styles.banner}>
        <div className={styles.message}>
          <span className={styles.mainMessage}>{MAIN_MESSAGE}</span>
          {ADDITIONAL_MESSAGE}
        </div>
        <div>
          <Link
            className={styles.scheduleInterviewLink}
            href={LINK}
            target="_blank"
            rel="noreferrer"
          >
            {BUTTON_NAME}
          </Link>
          <Button className={styles.dismissButton} onClick={dismiss} inline>
            {'Dismiss'}
          </Button>
        </div>
      </div>
    </>
  )
}

export default PipelinesInterviewRecruitmentBanner
