import {
  getBuildTypeHref,
  getFavoriteBuildsHref,
  getPipelineHref,
  getProjectHref,
} from '../../../../../routes'
import type {ProjectsTreeItem} from '../../../../../types/projectTrees'

import type {ProjectSidebarData} from './ProjectsSidebar.slices'
import {projectsSidebar} from './ProjectsSidebar.slices'

export const getBaseHref = (item: ProjectsTreeItem) => {
  switch (item.itemType) {
    case 'project':
      return getProjectHref(item.id, item.group === 'all')

    case 'pipeline':
      return getPipelineHref(item.id)

    case 'buildType':
      return getBuildTypeHref(item.id, item.group === 'all')

    case 'link':
      return getFavoriteBuildsHref()

    default:
      return null
  }
}

export const toProjectsSidebarState = (preloadedState?: Partial<ProjectSidebarData>) => ({
  ...projectsSidebar.getInitialState(),
  ...preloadedState,
})
