import {produce} from 'immer'

import {restBaseApi} from '../../../../services/restBase'
import type {PipelineId, ProjectId} from '../../../../types'
import {
  getPipelinesSettingsWithoutDeprecatedFields,
  getPreformattingIntegrations,
  getPreformattingSettings,
  getPreformattingVcsRoot,
  getPreformattingVcsRoots,
  parsePipeline,
  stringifyPipeline,
} from '../EditPipelinePage/EditPipelinePage.utils'
import {getAccountRootProjectId} from '../PipelinesPages.consts'

import type {
  NewPipelineDto,
  PipelineDto,
  Pipeline,
  UpdatePipelineArg,
  NewPipeline,
  GetRepositoryBranchesArg,
  RepositoryTestConnectionArg,
  PipelineDurations,
  RunDurations,
  PipelineRunnersJsonFromXMLs,
  GetParametersResolveArg,
  CheckVersionedSettingsArg,
  PipelineParametersResolve,
  CreateNewPipelineArg,
  PipelineProviderJdk,
  GetBuildStepDescriptionArg,
  GetBuildStepDescription,
  AgentCompatibilitiesArg,
  AgentCompatibilities,
  JobMapAgentCompatibilities,
  GetCompatibilityAgentsQueuedJobArg,
  VcsProvider,
  GetRepositoriesArg,
  GetRepositoriesResponse,
  GetPipelineRunVcsRootsArg,
  VcsRootDto,
  DebugArg,
  DebugResponse,
  GetProjectSshKeysArg,
  GetPipelineSshKeysArg,
  ProjectSshKeys,
  NotificationsArg,
  PersonalNotificationsDto,
} from './pipelinesApi.types'

const url = '/app/pipeline'
const urlAppRestPipelines = 'app/rest/pipelines'
const urlAppRestProjects = 'app/rest/projects'

const processNewPipeline = ({
  vcsRoot,
  settings,
  integrations,
  additionalVcsRoots,
  ...rest
}: NewPipeline): NewPipelineDto => ({
  ...rest,
  vcsRoot: produce(vcsRoot, getPreformattingVcsRoot), // TODO: remove after backend refactoring
  additionalVcsRoots: produce(additionalVcsRoots, getPreformattingVcsRoots),
  integrations: produce(integrations, getPreformattingIntegrations),
  yaml: stringifyPipeline(settings, {
    replacer: getPreformattingSettings,
    noRefs: true,
  }),
})

function tryToParsePipeline(pipelineYaml: string) {
  try {
    let settings = {}
    let yaml = pipelineYaml

    if (pipelineYaml) {
      const yamlJsonPipeline = parsePipeline(pipelineYaml)

      settings = getPipelinesSettingsWithoutDeprecatedFields(yamlJsonPipeline)
      yaml = stringifyPipeline(settings)
    }

    return {
      yaml,
      settings,
    }
  } catch (error) {
    // eslint-disable-next-line no-console
    console.error(error)
    return {yaml: pipelineYaml, settings: {}}
  }
}

const processPipeline = ({yaml, ...rest}: PipelineDto): Pipeline => {
  const yamlSettings = tryToParsePipeline(yaml)

  return {...rest, ...yamlSettings}
}

export const pipelinesApi = restBaseApi.injectEndpoints({
  endpoints: build => ({
    getRepositoryBranches: build.query<string[], GetRepositoryBranchesArg>({
      query: ({parentProjectId = getAccountRootProjectId(), ...queryArg}) => ({
        url: `${url}/repository/branches?parentProjectExtId=${parentProjectId}`,
        method: 'POST',
        body: queryArg,
      }),
      transformResponse: (data: {values: string[]}) => data.values,
    }),
    repositoryTestConnection: build.mutation<
      {status: 'OK' | 'ERROR'; errors?: {message: string}[]},
      RepositoryTestConnectionArg
    >({
      query: ({parentProjectId = getAccountRootProjectId(), body}) => ({
        url: `${url}/repository/testConnection?parentProjectExtId=${parentProjectId}`,
        method: 'POST',
        body,
      }),
    }),
    checkVersionedSettings: build.query<boolean, CheckVersionedSettingsArg>({
      query: queryArg => ({
        url: `${url}/repository/checkVersionedSettings`,
        method: 'POST',
        body: queryArg,
      }),
    }),
    getAllPipelines: build.query<Pipeline[], {parentProjectId?: ProjectId}>({
      query: ({parentProjectId = getAccountRootProjectId()}) => ({
        url: `${url}?parentProjectExtId=${parentProjectId}`,
      }),
      transformResponse: (data: PipelineDto[]) => data.map(processPipeline),
      providesTags: data => [
        ...(data?.map(({id}) => ({type: 'Pipeline' as const, id})) ?? []),
        {type: 'Pipeline', id: 'LIST'},
      ],
    }),
    getPipelineById: build.query<Pipeline, string>({
      query: id => ({url: `${url}/${id}`}),
      transformResponse: processPipeline,
      providesTags: data => [{type: 'Pipeline', id: `${data?.id}-SINGLE`}],
    }),
    createNewPipeline: build.mutation<Pipeline, CreateNewPipelineArg>({
      query: ({parentProjectId = getAccountRootProjectId(), body}) => ({
        url: `${url}?parentProjectExtId=${parentProjectId}`,
        method: 'POST',
        body: processNewPipeline(body),
      }),
      transformResponse: processPipeline,
      invalidatesTags: (_, error) =>
        error == null ? [{type: 'Pipeline', id: 'LIST'}, 'AllProjects', 'Overview'] : [],
    }),
    updatePipeline: build.mutation<Pipeline, UpdatePipelineArg>({
      query: ({id, body}) => ({
        url: `${url}/${id}`,
        method: 'POST',
        body: processNewPipeline(body),
      }),
      transformResponse: processPipeline,
      invalidatesTags: (_, __, {id}) => [{type: 'Pipeline', id}],
      async onQueryStarted({id}, {dispatch, queryFulfilled}) {
        const {data} = await queryFulfilled
        dispatch(pipelinesApi.util.updateQueryData('getPipelineById', id, () => data))
      },
    }),
    deletePipeline: build.mutation<void, string>({
      query: id => ({url: `${url}/${id}`, method: 'DELETE'}),
      invalidatesTags: (_, __, id) => [
        {type: 'Pipeline', id},
        {type: 'Pipeline', id: `${id}-SINGLE`},
        'AllProjects',
        'Overview',
      ],
    }),
    getRunOptimizations: build.query<RunDurations, {pipelineId: PipelineId; runId: number}>({
      query: ({pipelineId, runId}) => ({
        url: `${url}/${pipelineId}/${runId}/optimizations`,
      }),
    }),
    getPipelineOptimizations: build.query<
      PipelineDurations,
      {pipelineId: PipelineId; branch: string}
    >({
      query: ({pipelineId, branch}) => ({
        url: `${url}/${pipelineId}/optimizations`,
        params: {branch},
      }),
    }),
    getPipelineRunnersJsonFromXMLs: build.query<PipelineRunnersJsonFromXMLs, void>({
      query: () => ({
        url: `${url}/runners/jsonFromXMLs`,
      }),
    }),
    getPipelineProviderJdk: build.query<PipelineProviderJdk[], void>({
      query: () => ({
        url: `${url}/provider/jdk`,
      }),
      transformResponse: (data: {values: PipelineProviderJdk[]}) => data.values,
    }),
    getParametersResolve: build.query<PipelineParametersResolve[], GetParametersResolveArg>({
      query: ({id, body}) => ({
        url: `${url}/${id}/parameters/resolve`,
        method: 'POST',
        body: {
          ...body,
          pipeline: processNewPipeline(body.pipeline),
        },
      }),
      transformResponse: (data: {matches: PipelineParametersResolve[]}) => data.matches,
    }),
    getBuildStepDescription: build.query<GetBuildStepDescription, GetBuildStepDescriptionArg>({
      query: ({id, body}) => ({
        url: `${url}/${id}/buildStepDescription`,
        method: 'POST',
        body: processNewPipeline(body),
      }),
    }),
    agentCompatibilities: build.query<AgentCompatibilities, AgentCompatibilitiesArg>({
      query: queryArg => ({
        url: `${url}/${queryArg.pipelineId}/compatibility/agents/${queryArg.jobId}`,
        method: 'POST',
        body: processNewPipeline(queryArg.body),
      }),
    }),
    jobMapAgentCompatibilities: build.query<JobMapAgentCompatibilities, AgentCompatibilitiesArg>({
      query: queryArg => ({
        url: `${url}/${queryArg.pipelineId}/compatibility/agents`,
        method: 'POST',
        body: processNewPipeline(queryArg.body),
      }),
    }),
    getCompatibilityAgentsQueuedJob: build.query<
      AgentCompatibilities,
      GetCompatibilityAgentsQueuedJobArg
    >({
      query: queryArg => ({
        url: `${url}/${queryArg.pipelineId}/compatibility/agents/queuedJob/${queryArg.buildId}`,
      }),
    }),
    getVcsProviders: build.query<VcsProvider[], {parentProjectId?: ProjectId}>({
      query: ({parentProjectId = getAccountRootProjectId()}) => ({
        url: `${url}/provider/vcs?parentProjectExtId=${parentProjectId}`,
      }),
      transformResponse: (data: {values: VcsProvider[]}) => data.values,
    }),
    getRepositories: build.query<GetRepositoriesResponse, GetRepositoriesArg>({
      query: ({connectionId, parentProjectId = getAccountRootProjectId(), ...queryParams}) => ({
        url: `${url}/provider/vcs/${connectionId}/repositories`,
        params: {
          parentProjectExtId: parentProjectId,
          ...queryParams,
        },
      }),
    }),
    getPipelineRunVcsRoots: build.query<VcsRootDto[], GetPipelineRunVcsRootsArg>({
      query: ({pipelineId, runId}) => ({
        url: `${url}/${pipelineId}/${runId}/vcsRoots`,
      }),
      transformResponse: (data: {values: VcsRootDto[]}) => data.values,
    }),
    runPipelineDebug: build.query<DebugResponse, DebugArg>({
      query: ({pipelineId, body, fields}) => ({
        url: `${urlAppRestPipelines}/${pipelineId}/run`,
        method: 'POST',
        body,
        params: {
          fields,
        },
      }),
    }),
    getPersonalNotifications: build.query<PersonalNotificationsDto, NotificationsArg>({
      query: ({pipelineId}) => ({url: `${url}/${pipelineId}/notifications`}),
      providesTags: _ => [{type: 'Pipeline', id: 'PersonalNotifications'}],
    }),
    setPersonalNotifications: build.mutation<
      void,
      {notifications: PersonalNotificationsDto; pipelineId: PipelineId}
    >({
      query: queryArg => ({
        url: `${url}/${queryArg.pipelineId}/notifications`,
        method: 'POST',
        body: queryArg.notifications,
      }),
      invalidatesTags: (_, __) => [{type: 'Pipeline', id: 'PersonalNotifications'}],
    }),
    getProjectSshKeys: build.query<ProjectSshKeys, GetProjectSshKeysArg>({
      query: ({projectId}) => ({
        url: `${urlAppRestProjects}/${projectId}/sshKeys`,
      }),
    }),
    getPipelineSshKeys: build.query<VcsRootDto[], GetPipelineSshKeysArg>({
      query: ({pipelineId}) => ({
        url: `${urlAppRestPipelines}/${pipelineId}/sshKeys`,
      }),
      transformResponse: (data: {values: VcsRootDto[]}) => data.values,
    }),
    uploadPipelineSshKey: build.mutation<
      undefined,
      {pipelineId: PipelineId; file: File; fileName: string}
    >({
      query: ({pipelineId, file, fileName}) => {
        const formData = new FormData()

        formData.append('file', file)
        formData.append('fileName', fileName)

        return {
          url: `${urlAppRestPipelines}/${pipelineId}/sshKeys`,
          method: 'POST',
          body: formData,
          responseHandler: 'text',
        }
      },
    }),
    uploadProjectSshKey: build.mutation<
      undefined,
      {projectId: string; file: string; fileName: string}
    >({
      query: ({projectId, file, fileName}) => ({
        url: `${urlAppRestProjects}/${projectId}/sshKeys?fileName=${fileName}`,
        method: 'POST',
        headers: {
          'Content-Type': 'text/plain',
          Accept: 'application/json',
        },
        body: file,
      }),
    }),
  }),
})
