import {createSelector} from 'reselect'

import type {State} from '../../../../../reducers/types'

import type {ProjectSidebarData} from './ProjectsSidebar.slices'

// If you change this function, update currentStorageVersion in persistState.ts and add the old version to oldStorageVersions
export const getProjectsSidebarStateToPersist: (state: State) => Partial<ProjectSidebarData> =
  createSelector(
    (state: State) => state.projectsSidebar,
    ({activeItem, showArchivedProjects, ...sidebar}) => ({
      ...(window.internalProps['teamcity.ui.sidebar.saveSearchState'] ? sidebar : {}),
      showArchivedProjects,
      allProjectsCollapsed: true,
    }),
  )
