export const getIsAllSubtreeCollapsed: (
  arg0: State,
  arg1: ProjectsTree | null | undefined,
) => boolean = createSelector(
  (_: State, tree: ProjectsTree | null | undefined) => tree,
  (state: State) => state.blocks[CollapsibleBlock.COLLAPSED_PIPELINE] ?? getEmptyHash(),
  (state: State) => state.blocks[CollapsibleBlock.COLLAPSED_BUILDTYPE] ?? getEmptyHash(),
  (state: State) => state.blocks[CollapsibleBlock.COLLAPSED_SUBPROJECT] ?? getEmptyHash(),
  (subprojectTree, pipelineBlocks, buildTypeBlocks, subprojectBlocks) => {
    if (!subprojectTree) {
      return false
    }

    for (let i = 0; i < subprojectTree.data.length; i++) {
      const item = subprojectTree.data[i]

      if (
        (item.itemType === 'pipeline' && pipelineBlocks[item.id!] !== false) ||
        (item.itemType === 'buildType' && buildTypeBlocks[item.id!] !== false) ||
        (item.itemType === 'project' && subprojectBlocks[item.id] !== false)
      ) {
        return false
      }
    }

    return true
  },
)

