export const getTabUrl = (
  {projectId, buildTypeId, buildId, pipelineId, runId, jobId, batchId}: ActiveEntityProps,
  tab: TabId,
): string | undefined => {
  if (projectId == null && buildTypeId == null && buildId == null && pipelineId == null) {
    return undefined
  }

  const currentSearch = new URLSearchParams(location.search)
  const tabValue = String(tab)

  if (pipelineId) {
    currentSearch.set('tab', tabValue)
    if (jobId) {
      currentSearch.set('job', jobId)
    }
    if (batchId) {
      currentSearch.set('pageFullLogBuildId', batchId)
    }
  } else if (buildId != null) {
    currentSearch.set('buildTab', tabValue)
  } else if (buildTypeId) {
    currentSearch.set('buildTypeTab', tabValue)
  } else {
    currentSearch.set('projectTab', tabValue)
  }

  return `${getOverviewHref({
    projectId,
    buildTypeId,
    buildId,
    pipelineId,
    runId,
  })}?${currentSearch.toString()}`
}
