export function useBuildHref(buildId: BuildId | null | undefined, isAllProjects?: boolean) {
  const buildTypeId = useAppSelector(state => getBuild(state, buildId)?.buildType)
  const pipelineId = useAppSelector(state => getPipelineIdFromBuildId(state, buildId))
  const runId = useAppSelector(state => getPipelineRunIdFromBuildId(state, buildId))

  if (pipelineId != null) {
    return getPipelineHref(pipelineId, runId)
  }
  if (buildId != null) {
    return getBuildHref(buildId, buildTypeId, isAllProjects)
  }
  return null
}
export function useBuildHrefWithSaveParams(
  location: Location,
  buildId: BuildId | null | undefined,
  savedParams: ReadonlyArray<string>,
  isAllProjects = false,
): string {
  const href = useBuildHref(buildId, isAllProjects)
  return getHrefWithQueryParams(location, href, params =>
    savedParams.reduce(
      (acc, paramName) =>
        params[paramName] != null ? {...acc, [paramName]: String(params[paramName])} : acc,
      {},
    ),
  )
}

const useLocationSelector = <T>(selector: (location: Location) => T): T => selector(useLocation())

const useMatchSelector = <T>(route: string, selector: (match: PathMatch | null) => T): T =>
  useLocationSelector(location => selector(matchRoute(route, location.pathname)))

