type SyncedQueryParamArg = {
  param: string
  userProperty: string
  values?: ReadonlyArray<string>
  defaultValue?: string | null
  skip?: boolean
}
export const useQueryParams = () => {
  const [params] = useSearchParams()
  return searchParamsToObject(params)
}
export const useQueryParam = (param: string, defaultValue?: string | null | undefined) =>
  useQueryParams()[param] ?? defaultValue
type SetQueryParams = (
  params: (QueryParams | null | undefined) | ((prevParams: QueryParams) => QueryParams),
  replace?: boolean,
) => unknown
export const useSetQueryParams = (): SetQueryParams => {
  const location = useLocation()
  const navigate = useNavigate()
  return React.useCallback(
    (value, replace = true) => {
      const queryParams = queryToObject(location.search)
      const to = {
        hash: location.hash,
        search: objectToQuery(
          typeof value === 'function' ? value(queryParams) : mergeIfDifferent(queryParams, value),
        ),
      }
      navigate(to, {replace, preventScrollReset: true})
    },
    [location.hash, location.search, navigate],
  )
}
export type QueryParam = string | null | undefined
export type SetQueryParam = (value: QueryParam, replace?: boolean) => unknown
export const useSetQueryParam = (param: string, defaultValue?: QueryParam): SetQueryParam => {
  const setQueryParams = useSetQueryParams()
  return React.useCallback(
    (value, replace) =>
      setQueryParams(
        {
          [param]: value === defaultValue ? null : value,
        },
        replace,
      ),
    [defaultValue, param, setQueryParams],
  )
}
export const useQueryParamState = (
  param: string,
  defaultValue?: QueryParam,
): [QueryParam, SetQueryParam] => [
  useQueryParam(param, defaultValue),
  useSetQueryParam(param, defaultValue),
]
const defaultSyncedQueryValues: Record<string, string | undefined> = {}

function validateDefaultSyncedQueryValue(userProperty: string, value: string | undefined) {
  const existingDefaultValue = defaultSyncedQueryValues[userProperty]

  if (existingDefaultValue == null) {
    defaultSyncedQueryValues[userProperty] = value
  } else if (existingDefaultValue !== value) {
    // eslint-disable-next-line no-console
    console.warn(
      `Warning: The default value for the user property '${userProperty}' is being changed from '${existingDefaultValue}' to '${value}'. This may cause unexpected behavior.`,
    )
  }

  return defaultSyncedQueryValues[userProperty]
}

export function useSyncedQueryParam(
  params: SyncedQueryParamArg,
): [string | undefined, (newValue: string, skipNavigate?: boolean) => unknown] {
  const {param, userProperty, values, skip} = params
  const validate = (value: string | null | undefined) =>
    values != null ? values.find(item => item === value) : value

  const defaultValue = params.defaultValue ?? undefined
  const [queryValue, setQueryValue] = useQueryParamState(param)
  const validatedQueryValue = validate(queryValue)
  const userValue = useUserProperty(userProperty)
  const validatedUserValue = validate(userValue)
  const validatedDefaultValue =
    skip || process.env.NODE_ENV === 'test'
      ? defaultValue
      : validateDefaultSyncedQueryValue(userProperty, defaultValue)
  const value = validatedQueryValue ?? validatedUserValue ?? validatedDefaultValue ?? values?.[0]

  React.useEffect(() => {
    // TODO remove when https://github.com/remix-run/react-router/pull/8851 is merged
    if (skip || process.env.NODE_ENV === 'test') {
      return
    }

    const desiredQueryValue = value === validatedDefaultValue ? undefined : value
    if (queryValue !== desiredQueryValue) {
      setQueryValue(desiredQueryValue)
    }
  }, [value, queryValue, setQueryValue, skip, validatedDefaultValue])
  const setUserProperty = useSetUserProperty()
  return [
    value,
    React.useCallback(
      (newValue: string, skipNavigate = false) => {
        if (!skipNavigate) {
          setQueryValue(newValue)
        }

        setUserProperty(userProperty, newValue)
      },
      [setUserProperty, userProperty, setQueryValue],
    ),
  ]
}

type SyncedBooleanQueryParamArg = {
  readonly param: string
  readonly userProperty: string
  readonly defaultTrue?: boolean
  readonly skip?: boolean
}

export function useSyncedBooleanQueryParam({
  param,
  userProperty,
  defaultTrue = false,
  skip,
}: SyncedBooleanQueryParamArg): [boolean, (newValue: boolean, skipNavigate?: boolean) => unknown] {
  const [value, setValue] = useSyncedQueryParam({
    param,
    userProperty,
    values: ['true', 'false'],
    defaultValue: String(defaultTrue),
    skip,
  })
  return [
    value === 'true',
    React.useCallback(
      (newValue, skipNavigate) => setValue(String(newValue), skipNavigate),
      [setValue],
    ),
  ]
}

export const useBranch = (): Branch | null | undefined => parseBranch(useQueryParam('branch'))
export const useBuildIdFromPath = (): BuildId | null | undefined => {
  const branch = useBranch()
  const buildLocator = useMatchSelector(Routes.BUILD, matched => {
    const {buildId, buildTypeId: buildTypeIdString} = matched?.params ?? {}
    const buildTypeId = buildTypeIdString != null ? toBuildTypeId(buildTypeIdString) : undefined
    return getBuildOrPermalinkLocator(buildId, buildTypeId, branch)
  })

  const fromBuildUnknownBuildTypePath = useMatchSelector(
    Routes.BUILD_UNKNOWN_BUILDTYPE,
    matched => {
      const id = matched?.params.buildId
      return id != null ? toBuildId(id) : undefined
    },
  )

  const {actualBuildId} = restApi.endpoints.getBuildNormalizedAsList.useQuery(
    buildLocator ? getSingleBuildArg(buildLocator) : skipToken,
    {
      selectFromResult: ({data}) => ({
        actualBuildId: data?.result[0],
      }),
    },
  )

  return actualBuildId || toBuildId(getIdFromLocator(buildLocator)) || fromBuildUnknownBuildTypePath
}
export const useBuildId = (): BuildId | null | undefined => {
  const {buildId} = React.useContext(EntityContext)
  const fromPath = useBuildIdFromPath()
  return buildId ?? fromPath
}
