export const useIsAgentsPartSelected = (): boolean => {
  const location = useLocation()
  const agent = useIsAgentSelected()
  const overview = getIsAgentsOverviewSelected(location.pathname)
  const unauthorizedAgents = getIsUnauthorizedAgentsSelected(location.pathname)
  const root = getIsAgentsRootSelected(location.pathname)
  const pool = useIsAgentsPoolSelected()
  const cloud = useIsCloudImageSelected()
  const favoriteAgentPools = getIsFavoriteAgentPoolsSelected(location.pathname)
  return agent || overview || unauthorizedAgents || root || pool || cloud || favoriteAgentPools
}
