export function usePrevLocation() {
  const location = useLocation()
  const prevLocation = useDerivedState(location, prevState =>
    browserHistory.createHref(location) !== browserHistory.createHref(prevState)
      ? location
      : prevState,
  )
  return browserHistory.createHref(prevLocation) !== browserHistory.createHref(location)
    ? prevLocation
    : null
}
export const useBooleanQueryParam = (param: string): boolean => {
  const stringValue = useQueryParam(param)
  return stringValue === 'true'
}
export const withQueryParam: (arg0: string) => HOC<any, any> = param =>
  withHook(() => ({
    [param]: useQueryParam(param),
  }))
type SetBooleanQueryParam = (value: boolean, replace?: boolean) => unknown

function useSetBooleanQueryParam(param: string, defaultTrue = false): SetBooleanQueryParam {
  const setQueryParam = useSetQueryParam(param, String(defaultTrue))
  return React.useCallback(
    (
      value,
      replace, // omit param if its value is default
    ) => setQueryParam(String(value), replace),
    [setQueryParam],
  )
}

export const useBooleanQueryParamState = (
  param: string,
  defaultValue?: boolean,
): [boolean, SetBooleanQueryParam] => [
  useBooleanQueryParam(param),
  useSetBooleanQueryParam(param, defaultValue),
]
export const useHash = (): string => useLocationSelector(location => location.hash.slice(1))
type SetHash = (value: string, replace?: boolean) => unknown
export const useSetHash = (): SetHash => {
  const location = useLocation()
  const navigate = useNavigate()
  return React.useCallback(
    (value, replace = true) =>
      navigate(getHrefWithQueryParams(location, null, undefined, value), {
        replace,
        preventScrollReset: true,
      }),
    [location, navigate],
  )
}
export type BranchProps = {
  branch?: Branch | null
}
export const withBranchProps: Enhancer<BranchProps, any> = withHook(() => {
  const branchQueryParam = useQueryParam('branch')
  const branch = parseBranch(branchQueryParam)
  return branchQueryParam !== undefined
    ? {
        branch, // null - all branches
      }
    : {} // undefined - branch not specified
})
const favoriteBuildsItem = {
  nodeType: 'link',
  id: toCustomSidebarItemId(getFavoriteBuildsHref()),
} as const
const overviewProjectsItem = {
  nodeType: 'link',
  id: toCustomSidebarItemId(getFavoriteProjectsHref()),
} as const
export const withActivatedByUrlItem = withHook(() => {
  const location = useLocation()
  const isFavoriteBuildsLinkSelected = getIsFavoriteBuildsLinkSelected(location.pathname)
  const isFavoriteProjectsLinkSelected = useIsFavoriteProjectsLinkSelected()
  const projectOrBuildTypeNode = useProjectOrBuildTypeNode()
  const hash = useHash()
  const isAllProjects = hash === ALL_PROJECTS_HASH
  const {currentId, currentNodeType} = useContext(ProjectsTreeContext)
  const activeItem: SidebarActiveItem | null = React.useMemo(() => {
    const group = isAllProjects ? 'all' : 'favorites'
    if (currentId != null && currentNodeType != null) {
      return currentNodeType === 'project'
        ? {nodeType: currentNodeType, id: toProjectId(currentId), group}
        : {nodeType: currentNodeType, id: toBuildTypeId(currentId), group}
    }

    if (isFavoriteBuildsLinkSelected) {
      return favoriteBuildsItem
    }

    if (isFavoriteProjectsLinkSelected) {
      return overviewProjectsItem
    }

    return (
      projectOrBuildTypeNode && {
        ...projectOrBuildTypeNode,
        group,
      }
    )
  }, [
    currentId,
    currentNodeType,
    isAllProjects,
    isFavoriteBuildsLinkSelected,
    isFavoriteProjectsLinkSelected,
    projectOrBuildTypeNode,
  ])

  return {
    activeItem,
  }
})

