class Node {
  className: string | null | undefined
  withIcon: boolean
  next: Record<string, Node> | null | undefined

  constructor(className: string | null | undefined, withIcon = false, next?: Record<string, Node>) {
    this.className = className
    this.withIcon = withIcon
    this.next = next
  }
}

