import {processResponse, request, getHeaders} from '@jetbrains/teamcity-ui/dist/services'
import type {FetchArgs} from '@reduxjs/toolkit/query'
import {createApi, fetchBaseQuery} from '@reduxjs/toolkit/query/react'

type RestFetchArgs = FetchArgs & {
  withAuth?: boolean
  withJsonError?: boolean
}

const baseQuery = ({responseHandler, withAuth = true}: RestFetchArgs) =>
  fetchBaseQuery({
    baseUrl: window.base_uri,
    credentials: 'include',
    prepareHeaders: headers => {
      if (responseHandler === 'text') {
        headers.set('Accept', 'text/plain')
      }
      return new Headers(getHeaders({headers}, withAuth))
    },
    fetchFn(input, init) {
      const options = typeof input === 'string' ? init : input
      const url = typeof input === 'string' ? input : input.url
      return request(url, null, options, withAuth)
    },
  })

type GetUserFieldApiResponse = string
type GetUserFieldApiArg = {
  userLocator: string
  field: string
}
type GetUserPropertyApiResponse = string
type GetUserPropertyApiArg = {
  userLocator: string
  name: string
}
type SetUserPropertyApiResponse = string
type SetUserPropertyApiArg = {
  userLocator: string
  name: string
  body: string
}

export const restBaseApi = createApi({
  reducerPath: 'restApi',
  baseQuery: (arg: RestFetchArgs, ...args) =>
    baseQuery(arg)(
      {
        responseHandler: response => {
          const responseClone = response.clone()

          return processResponse(response)
            .then(
              data => data,
              () => (arg.withJsonError ? responseClone.json() : responseClone.text()),
            )
            .catch(error => error)
        },
        validateStatus: response => response.ok,
        ...arg,
      },
      ...args,
    ),
  tagTypes: [
    'Build',
    'Agent',
    'Pipeline',
    'Overview',
    'AllProjects',
    'CleanupRules',
    'CleanupPolicies',
  ],
  endpoints: build => ({
    getUserField: build.query<GetUserFieldApiResponse, GetUserFieldApiArg>({
      query: queryArg => ({
        url: `/app/rest/users/${queryArg.userLocator}/${queryArg.field}`,
        responseHandler: 'text',
      }),
    }),
    getUserProperty: build.query<GetUserPropertyApiResponse, GetUserPropertyApiArg>({
      query: queryArg => ({
        url: `/app/rest/users/${queryArg.userLocator}/properties/${queryArg.name}`,
        responseHandler: 'text',
      }),
    }),
    setUserProperty: build.mutation<SetUserPropertyApiResponse, SetUserPropertyApiArg>({
      query: queryArg => ({
        url: `/app/rest/users/${queryArg.userLocator}/properties/${queryArg.name}`,
        method: 'PUT',
        body: queryArg.body,
        headers: {
          'Content-Type': 'text/plain',
        },
        responseHandler: 'text',
      }),
      onQueryStarted({userLocator, name, body}, {dispatch, queryFulfilled}) {
        const patchResult = dispatch(
          restBaseApi.util.updateQueryData('getUserProperty', {userLocator, name}, () => body),
        )
        queryFulfilled.catch(patchResult.undo)
      },
    }),
  }),
  refetchOnMountOrArgChange: 5,
})
