import {safeLocalStorage} from '../../../../utils/safeStorages'

export const isCloud = window.internalProps['teamcity.cloud.enabled']
export const isProjectsAndBuildTypesEnabled = () =>
  window.internalProps['teamcity.pipelines.projects.enabled'] !== false
const isPipelinesEnabled = window.internalProps['teamcity.pipelines.enabled']
export const isPipelinesEnabledInExclusiveMode = () =>
  isPipelinesEnabled && !isProjectsAndBuildTypesEnabled()
export const isTestNpmConnectionEnabled =
  window.internalProps['teamcity.pipelines.testNpmConnection.enabled']
export const isUnityRunnerEnabled = window.internalProps['teamcity.pipelines.unity.enabled']
export const isPipelinesAgentPageEnabled = () =>
  isPipelinesEnabled &&
  window.internalProps['teamcity.pipelines.agentPage.enabled'] === true &&
  safeLocalStorage.getItem('isPipelinesAgentPageEnabled') !== 'false'
export const dependencyCacheEnabled =
  window.internalProps['teamcity.pipelines.dependencyCache.enabled']
export const isMuteInvestigateButtonEnabled =
  window.internalProps['teamcity.pipelines.muteInvestigateButton.enabled']
export const isPipelinesInterviewRecruitmentBannerEnabled =
  isPipelinesEnabledInExclusiveMode() &&
  window.internalProps['teamcity.pipelines.interviewRecruitmentBanner.enabled']
export const isNotificationsFeatureEnabled =
  window.internalProps['teamcity.pipelines.feature.notifications.enabled']
export const isPipelineNotificationsEnabled =
  window.internalProps['teamcity.pipelines.feature.pipeline.notifications.enabled']
export const isHideProjectTreeNumbersEnabled =
  window.internalProps['teamcity.ui.projectTree.hideNumbers.enabled']
// Temporary hide feature toggle
// Task: TCP-1363 Remove support for statuses of recent job runs in edit mode
export const isTemporaryHideFailedJobStateEditMode = true
export const isPipelineCompatibilityAgentsEnabled =
  window.internalProps['teamcity.pipelines.feature.compatibilityAgents.enabled']
export const isPipelinesFeedbackFormEnabled =
  window.internalProps['teamcity.pipelines.feedbackForm.enabled']
export const isStatusPublishingFeatureEnabled =
  window.internalProps['teamcity.pipelines.statusPublishing.configuration.enabled']
export const isCreateProjectNewUiEnabled =
  window.internalProps['teamcity.ui.createProject.newui.enabled']
export const isWithoutVcsFeatureEnabled =
  window.internalProps['teamcity.pipelines.feature.withoutVcs.enabled']
export const isWelcomePopupEnabled = () =>
  isPipelinesEnabled &&
  !isPipelinesEnabledInExclusiveMode() &&
  window.internalProps['teamcity.pipelines.welcomePopup.enabled'] === true
export const isEarlyAccessLabelEnabled =
  window.internalProps['teamcity.pipelines.earlyAccessLabel.enabled']
export const isPipelinesClassicUIBannerEnabled =
  window.internalProps['teamcity.pipelines.classicUIBanner.enabled']
export const isPullRequestsFeatureEnabled =
  window.internalProps['teamcity.pipelines.feature.pullRequests.enabled']
export const isTryPipelinesLinkEnabled =
  window.internalProps['teamcity.pipelines.tryPipelinesLink.enabled']
export const isTestDriveJobEnabled = window.internalProps['teamcity.pipelines.feature.testDriveJob']
export const isFeedbackCSATEnabled = window.internalProps['teamcity.feedback.csat.enabled']
export const isFeedbackCSATTestingEnabled =
  window.internalProps['teamcity.feedback.csat.testing.enabled']
export const isTechInsightsPanelEnabled =
  window.internalProps['teamcity.feedback.csat.techInsightsPanel.enabled']
